export function laneGraphNodes(lanes: readonly string[]): DefinitionNode[] {
  return [
    ...lanes.map(lane => ({ node_id: `launch_${lane}`, label: `Launch ${lane} worker`, kind: 'worker' as const, depends_on: [] })),
